// Clean-room TSVC s1213 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const bits=@as(u64,@bitCast(v));for(0..8)|j|out[p+j]=@truncate(bits>>(8*j));}
pub export fn tsvc_s1213_ordered_neighbor_array_map(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<13 or length>129)return -1;const v=input.?[0..length];const nr=v[0];if(nr<3 or nr>32)return -1;const n:usize=@intCast(nr);if(length!=1+4*n)return -1;var a=[_]i64{0}**32;var b=[_]i64{0}**32;var c=[_]i64{0}**32;var d=[_]i64{0}**32;for(0..n)|i|{const x=v[1+i];const y=v[1+n+i];const z=v[1+2*n+i];const w=v[1+3*n+i];if(x< -1 or x>1 or y< -1 or y>1 or z< -1 or z>1 or w< -1 or w>1)return -1;a[i]=x;b[i]=y;c[i]=z;d[i]=w;}if(output==null or capacity<16*n)return -2;for(1..n-1)|i|{a[i]=b[i-1]+c[i];b[i]=a[i+1]*d[i];}for(0..n)|i|{put64(output.?,8*i,a[i]);put64(output.?,8*(n+i),b[i]);}return @intCast(2*n);}
